// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }
    function testFuzz_property(uint256 newLimit) public {
        newLimit = bound(newLimit, 1, 1e18);
        vm.assume(newLimit > 0);

        // Owner calls AdjustBetAmounts
        c.AdjustBetAmounts(newLimit);

        // Open to public to allow wager/play
        c.OpenToThePublic();

        // Simulate a contract caller (eoa1 is an EOA, address(1337) is a contract)
        address eoa = address(0x1234);
        vm.deal(eoa, newLimit);
        vm.prank(eoa, eoa); // EOA: msg.sender == tx.origin
        c.wager{value: newLimit}();

        // Now try to call play from a contract (msg.sender != tx.origin)
        address contractAddr = address(0x1337);
        // We need to craft a call where msg.sender is contractAddr and tx.origin is eoa
        // Using prank(msg.sender, tx.origin) cheatcode
        vm.prank(contractAddr, eoa);
        // This should revert in reference C (msg.sender != tx.origin) but might succeed in mutant
        (bool success,) = address(c).call(abi.encodeWithSelector(c.play.selector));

        // The rule: the play() call from a contract should revert
        assertTrue(!success, "Contract should not be able to play");
    }
}

